import React from "react";
import "./Navbar.css";

const Navbar = () => {
  return (
    <nav className="navbar">
      <div className="navbar-container">

        <div className="navbar-logo">
          Course App
        </div>

        <ul className="navbar-links">
          <li>Home</li>
          <li>Courses</li>
          <li>About</li>
        </ul>

      </div>
    </nav>
  );
};

export default Navbar;
